    public function testAdminDbBackupRestoreTestBackupOverwrite(): void
    {
        $server = TestServer::new();
        $owner = next_user_name();
        $db = next_db_name();
        $server->api->user_login("admin", "admin");
        $server->api->admin_user_add($owner, $owner);
        $server->api->admin_db_add($owner, $db, "mapped");
        $queries = [
            QueryBuilder::insert()
                ->nodes()
                ->aliases(["root"])
                ->query(),
        ];
        $server->api->admin_db_exec_mut($owner, $db, $queries);
        $status = $server->api->admin_db_backup($owner, $db);
        $this->assertEquals($status, 201);
        $this->assertTrue(
            count(
                array_filter(
                    $server->api->admin_db_list()[1],
                    fn($d) => $d->owner === $owner &&
                        $d->db === $db &&
                        $d->backup !== 0
                )
            ) > 0
        );
        $queries_2 = [QueryBuilder::remove()->ids("root")->query()];
        $server->api->admin_db_exec_mut($owner, $db, $queries_2);
        $status_2 = $server->api->admin_db_backup($owner, $db);
        $this->assertEquals($status_2, 201);
        $this->assertTrue(
            count(
                array_filter(
                    $server->api->admin_db_list()[1],
                    fn($d) => $d->owner === $owner &&
                        $d->db === $db &&
                        $d->backup !== 0
                )
            ) > 0
        );
        $status_3 = $server->api->admin_db_restore($owner, $db);
        $this->assertEquals($status_3, 201);
        $queries_3 = [QueryBuilder::select()->ids("root")->query()];
        $results = unwrap_err(
            fn() => $server->api->admin_db_exec($owner, $db, $queries_3)
        )->description;
        $this->assertEquals($results, 'Alias \'root\' not found');
    }

