        $server->api->admin_db_add($owner, $db, "mapped");
        $queries = [
            QueryBuilder::insert()
                ->nodes()
                ->aliases(["root"])
                ->query(),
        ];
        $server->api->admin_db_exec_mut($owner, $db, $queries);
        $status = $server->api->admin_db_copy($owner, $db, $owner, $db2);
        $this->assertEquals($status, 201);
        $this->assertTrue(
            count(
                array_filter(
                    $server->api->admin_db_list()[1],
                    fn($d) => $d->owner === $owner && $d->db === $db2
                )
            ) > 0
        );
        $queries_2 = [QueryBuilder::select()->ids("root")->query()];
        $results = $server->api->admin_db_exec($owner, $db2, $queries_2)[1];
        $this->assertEquals(count($results), 1);
        $this->assertEquals($results[0]->result, 1);
        $this->assertEquals($results[0]->elements, [
            new DbElement(id: 1, from: 0, to: 0, values: []),
        ]);
    }

