    public function testAdminDbListTestDbList(): void
    {
        $server = TestServer::new();
        $owner1 = next_user_name();
        $owner2 = next_user_name();
        $db1 = next_db_name();
        $db2 = next_db_name();
        $server->api->user_login("admin", "admin");
        $server->api->admin_user_add($owner1, $owner1);
        $server->api->admin_user_add($owner2, $owner2);
        $server->api->admin_db_add($owner1, $db1, "memory");
        $server->api->admin_db_add($owner2, $db2, "memory");
        $tuple1 = $server->api->admin_db_list();
        $status = $tuple1[0];
        $list = $tuple1[1];
        $this->assertEquals($status, 200);
        $db1_entry =
            array_values(array_filter($list, fn($d) => $d->db === $db1))[0] ??
            (null ?? throw new \RuntimeException("the database is listed"));
        $this->assertEquals($db1_entry->owner, $owner1);
        $this->assertEquals($db1_entry->db_type, "memory");
        $this->assertEquals($db1_entry->role, "admin");
        $this->assertNotEquals($db1_entry->created, 0);
        $db2_entry =
            array_values(array_filter($list, fn($d) => $d->db === $db2))[0] ??
            (null ?? throw new \RuntimeException("the database is listed"));
        $this->assertEquals($db2_entry->owner, $owner2);
        $this->assertEquals($db2_entry->db_type, "memory");
        $this->assertEquals($db2_entry->role, "admin");
        $this->assertNotEquals($db2_entry->created, 0);
    }

