    public function testAdminUserLogoutTestLogoutSelectedSession(): void
    {
        $server = TestServer::new();
        $user = next_user_name();
        $server->api->user_login("admin", "admin");
        $server->api->admin_user_add($user, $user);
        $client1 = api_with_agent($server->api->address(), "admin-target-1");
        $client2 = api_with_agent($server->api->address(), "admin-target-2");
        $client1->user_login($user, $user);
        $client2->user_login($user, $user);
        $users = $server->api->admin_user_list()[1];
        $target =
            array_values(
                array_filter($users, fn($u) => $u->username === $user)
            )[0] ??
            (null ??
                throw new \RuntimeException(
                    "expected target user in user list"
                ));
        $session_id =
            (array_values(
                array_filter(
                    $target->sessions,
                    fn($s) => $s->agent === "admin-target-2"
                )
            )[0] ??
            null === null
                ? null
                : (fn($s) => $s->session)(
                    array_values(
                        array_filter(
                            $target->sessions,
                            fn($s) => $s->agent === "admin-target-2"
                        )
                    )[0] ?? null
                )) ??
            throw new \RuntimeException("expected session for revoked client");
        $server->api->admin_user_logout_session($user, $session_id);
        $status = $client1->user_status()[1];
        $this->assertEquals($status->username, $user);
        $this->assertTrue($status->login);
        $this->assertEquals(
            unwrap_err(fn() => $client2->user_status())->status,
            401
        );
    }

