    public function testClusterTestAdminClusterLogoutSelectedSession(): void
    {
        $cluster = TestCluster::new();
        $user = next_user_name();
        $admin = $cluster->follower();
        $admin->cluster_user_login("admin", "admin");
        $admin->admin_user_add($user, $user);
        $address = $admin->address();
        $client1 = api_with_agent($address, "cluster-admin-target-1");
        $client2 = api_with_agent($address, "cluster-admin-target-2");
        $client1->cluster_user_login($user, $user);
        $client2->cluster_user_login($user, $user);
        $session_id =
            (array_values(
                array_filter(
                    $client2->user_status()[1]->sessions,
                    fn($s) => $s->agent === "cluster-admin-target-2"
                )
            )[0] ??
            null === null
                ? null
                : (fn($s) => $s->session)(
                    array_values(
                        array_filter(
                            $client2->user_status()[1]->sessions,
                            fn($s) => $s->agent === "cluster-admin-target-2"
                        )
                    )[0] ?? null
                )) ??
            throw new \RuntimeException("expected session for revoked client");
        $admin->cluster_admin_user_logout_session($user, $session_id);
        $this->assertTrue($client1->user_status()[1]->login);
        $this->assertEquals(
            unwrap_err(fn() => $client2->user_status())->status,
            401
        );
    }

    public function testClusterTestDashboard(): void
    {
        $cluster = TestCluster::new();
        $user = next_user_name();
        $other = next_user_name();
        $client = $cluster->follower();
        $client->cluster_user_login("admin", "admin");
        $client->admin_user_add($user, $user);
        $client->admin_user_add($other, $other);
        $client->cluster_user_login($user, $user);
        $client->dashboard_add($user, "ops", "{}");
        $client->dashboard_save($user, "ops", '{"v":2}');
        $this->assertEquals(
            $client->dashboard_get($user, "ops")[1]->config,
            '{"v":2}'
        );
        $client->dashboard_rename($user, "ops", "sales");
        $client->dashboard_user_add($user, "sales", $other, "read");
        $client->user_home_dashboard_set($user, "sales");
        $leader = $cluster->leader();
        $leader->user_login($user, $user);
        $this->assertEquals(
            $leader->dashboard_get($user, "sales")[1]->config,
            '{"v":2}'
        );
        $this->assertEquals(
            $leader->user_home_dashboard()[1] === null
                ? null
                : (fn($d) => $d->name)($leader->user_home_dashboard()[1]),
            "sales"
        );
        $this->assertEquals(
            count($client->dashboard_user_list($user, "sales")[1]),
            2
        );
        $names = array_map(fn($d) => $d->name, $client->dashboard_list()[1]);
        $this->assertEquals($names, ["sales"]);
        $client->dashboard_public($user, "sales", true);
        $this->assertTrue($client->dashboard_get($user, "sales")[1]->public);
        $client->dashboard_public($user, "sales", false);
        $this->assertTrue(!$client->dashboard_get($user, "sales")[1]->public);
        $client->user_home_dashboard_clear();
        $client->dashboard_user_remove($user, "sales", $other);
        $this->assertEquals(
            count($client->dashboard_user_list($user, "sales")[1]),
            1
        );
        $client->dashboard_remove($user, "sales");
        $this->assertTrue(count($client->dashboard_list()[1]) === 0);
    }

    public function testDashboardTestAddGetList(): void
    {
        $server = TestServer::new();
        $user = next_user_name();
        $server->api->user_login("admin", "admin");
        $server->api->admin_user_add($user, $user);
        $server->api->user_login($user, $user);
        $status = $server->api->dashboard_add($user, "ops", '{"widgets":[]}');
        $this->assertEquals($status, 201);
        $server->api->dashboard_add($user, "alpha", "{}");
        $tuple1 = $server->api->dashboard_get($user, "ops");
        $status_2 = $tuple1[0];
        $dashboard = $tuple1[1];
        $this->assertEquals($status_2, 200);
        $this->assertEquals($dashboard->name, "ops");
        $this->assertEquals($dashboard->owner, $user);
        $this->assertEquals($dashboard->role, "admin");
        $this->assertEquals($dashboard->config, '{"widgets":[]}');
        $tuple2 = $server->api->dashboard_list();
        $status_3 = $tuple2[0];
        $list = $tuple2[1];
        $this->assertEquals($status_3, 200);
        $first =
            array_values(
                array_filter($list, fn($d) => $d->owner === $user)
            )[0] ??
            (null ?? throw new \RuntimeException("own dashboard listed"));
        $this->assertEquals($first->name, "alpha");
        $this->assertTrue(
            count(
                array_filter(
                    $list,
                    fn($d) => $d->owner === $user && $d->name === "ops"
                )
            ) > 0
        );
        $this->assertTrue(
            count(
                array_filter(
                    $list,
                    fn($d) => $d->owner !== $user ||
                        $d->name === "alpha" ||
                        $d->name === "ops"
                )
            ) === count($list)
        );
        $this->assertTrue(
            count(
                array_filter(
                    $list,
                    fn($d) => $d->owner !== $user ||
                        ($d->updated > 0 && $d->role === "admin")
                )
            ) === count($list)
        );
    }

