            fn() => $server->api->dashboard_user_list($owner, "ops")
        )->status;
        $this->assertEquals($status_3, 403);
        $server->api->user_login($member, $member);
        $tuple3 = $server->api->dashboard_list();
        $list_2 = $tuple3[1];
        $listed_2 =
            array_values(
                array_filter($list_2, fn($d) => $d->owner === $owner)
            )[0] ??
            (null ?? throw new \RuntimeException("dashboard listed"));
        $this->assertTrue($listed_2->public);
        $this->assertTrue($listed_2->member);
        $tuple4 = $server->api->dashboard_user_list($owner, "ops");
        $users = $tuple4[1];
        $this->assertEquals(count($users), 2);
        $server->api->user_login($owner, $owner);
        $tuple5 = $server->api->dashboard_list();
        $list_3 = $tuple5[1];
        $listed_3 =
            array_values(
                array_filter($list_3, fn($d) => $d->owner === $owner)
            )[0] ??
            (null ?? throw new \RuntimeException("dashboard listed"));
        $this->assertEquals($listed_3->role, "admin");
        $this->assertTrue($listed_3->public);
        $this->assertTrue($listed_3->member);
        $server->api->dashboard_rename($owner, "ops", "sales");
        $server->api->user_login($viewer, $viewer);
        $tuple6 = $server->api->dashboard_get($owner, "sales");
