    public function testDbBackupRestoreTestBackupOverwrite(): void
    {
        $server = TestServer::new();
        $owner = next_user_name();
        $db = next_db_name();
        $server->api->user_login("admin", "admin");
        $server->api->admin_user_add($owner, $owner);
        $server->api->user_login($owner, $owner);
        $server->api->db_add($owner, $db, "mapped");
        $queries = [
            QueryBuilder::insert()
                ->nodes()
                ->aliases(["root"])
                ->query(),
        ];
        $server->api->db_exec_mut($owner, $db, $queries);
        $status = $server->api->db_backup($owner, $db);
        $this->assertEquals($status, 201);
        $this->assertTrue(
            count(
                array_filter(
                    $server->api->db_list()[1],
                    fn($d) => $d->owner === $owner &&
                        $d->db === $db &&
                        $d->backup !== 0
                )
            ) > 0
        );
        $queries_2 = [QueryBuilder::remove()->ids("root")->query()];
        $server->api->db_exec_mut($owner, $db, $queries_2);
        $status_2 = $server->api->db_backup($owner, $db);
        $this->assertEquals($status_2, 201);
        $this->assertTrue(
            count(
                array_filter(
                    $server->api->db_list()[1],
                    fn($d) => $d->owner === $owner &&
                        $d->db === $db &&
                        $d->backup !== 0
                )
            ) > 0
        );
        $status_3 = $server->api->db_restore($owner, $db);
        $this->assertEquals($status_3, 201);
        $queries_3 = [QueryBuilder::select()->ids("root")->query()];
        $results = unwrap_err(
            fn() => $server->api->db_exec($owner, $db, $queries_3)
        )->description;
        $this->assertEquals($results, 'Alias \'root\' not found');
    }

