    public function testDbListTestList(): void
    {
        $server = TestServer::new();
        $owner = next_user_name();
        $user = next_user_name();
        $db1 = next_db_name();
        $db2 = next_db_name();
        $server->api->user_login("admin", "admin");
        $server->api->admin_user_add($owner, $owner);
        $server->api->admin_user_add($user, $user);
        $server->api->admin_db_add($owner, $db1, "memory");
        $server->api->admin_db_add($user, $db2, "memory");
        $server->api->admin_db_user_add($owner, $db1, $user, "read");
        $server->api->user_login($user, $user);
        $tuple1 = $server->api->db_list();
        $status = $tuple1[0];
        $list = $tuple1[1];
        $this->assertEquals($status, 200);
        $this->assertEquals(count($list), 2);
        $db1_entry =
            array_values(array_filter($list, fn($d) => $d->db === $db1))[0] ??
            (null ?? throw new \RuntimeException("the database is listed"));
        $this->assertEquals($db1_entry->owner, $owner);
        $this->assertEquals($db1_entry->db_type, "memory");
        $this->assertEquals($db1_entry->role, "read");
        $db2_entry =
            array_values(array_filter($list, fn($d) => $d->db === $db2))[0] ??
            (null ?? throw new \RuntimeException("the database is listed"));
        $this->assertEquals($db2_entry->owner, $user);
        $this->assertEquals($db2_entry->db_type, "memory");
        $this->assertEquals($db2_entry->role, "admin");
    }

