    public function testDbUserAddTestAddDbUser(): void
    {
        $server = TestServer::new();
        $owner = next_user_name();
        $user = next_user_name();
        $db = next_db_name();
        $server->api->user_login("admin", "admin");
        $server->api->admin_user_add($owner, $owner);
        $server->api->admin_user_add($user, $user);
        $server->api->user_login($owner, $owner);
        $server->api->db_add($owner, $db, "mapped");
        $status = $server->api->db_user_add($owner, $db, $user, "write");
        $this->assertEquals($status, 201);
        $server->api->user_login($user, $user);
        $list = $server->api->db_list()[1];
        $this->assertEquals(count($list), 1);
        $entry =
            array_values(array_filter($list, fn($d) => $d->db === $db))[0] ??
            (null ?? throw new \RuntimeException("the database is listed"));
        $this->assertEquals($entry->owner, $owner);
        $this->assertEquals($entry->db_type, "mapped");
        $this->assertEquals($entry->role, "write");
    }

