    public function testUserLogoutTestLogoutSelectedSession(): void
    {
        $server = TestServer::new();
        $user = next_user_name();
        $server->api->user_login("admin", "admin");
        $server->api->admin_user_add($user, $user);
        $client1 = api_with_agent($server->api->address(), "session-owner");
        $client2 = api_with_agent($server->api->address(), "session-revoked");
        $client1->user_login($user, $user);
        $client2->user_login($user, $user);
        $status = $client1->user_status()[1];
        $session_id =
            (array_values(
                array_filter(
                    $status->sessions,
                    fn($s) => $s->agent === "session-revoked"
                )
            )[0] ??
            null === null
                ? null
                : (fn($s) => $s->session)(
                    array_values(
                        array_filter(
                            $status->sessions,
                            fn($s) => $s->agent === "session-revoked"
                        )
                    )[0] ?? null
                )) ??
            throw new \RuntimeException("expected session for revoked client");
        $code = $client1->user_logout_session($session_id);
        $this->assertEquals($code, 201);
        $status_2 = $client1->user_status()[1];
        $this->assertEquals($status_2->username, $user);
        $this->assertTrue($status_2->login);
        $this->assertTrue(!$status_2->admin);
        $this->assertEquals(
            unwrap_err(fn() => $client2->user_status())->status,
            401
        );
    }

    public function testUserStatusUser(): void
    {
        $server = TestServer::new();
        $user = next_user_name();
        $server->api->user_login("admin", "admin");
        $server->api->admin_user_add($user, $user);
        $server->api->user_login($user, $user);
        $user_status = $server->api->user_status()[1];
        $this->assertEquals($user_status->username, $user);
        $this->assertTrue($user_status->login);
        $this->assertTrue(!$user_status->admin);
        $this->assertEquals(count($user_status->sessions), 1);
        $this->assertEquals(
            $user_status->sessions[0]->agent,
            test_agent_name()
        );
    }

    public function testUserStatusAdmin(): void
    {
        $server = TestServer::new();
        $server->api->user_login("admin", "admin");
        $user_status = $server->api->user_status()[1];
        $this->assertEquals($user_status->username, "admin");
        $this->assertTrue($user_status->login);
        $this->assertTrue($user_status->admin);
        $this->assertTrue(!(count($user_status->sessions) === 0));
        $this->assertTrue(
            count(
                array_filter(
                    $user_status->sessions,
                    fn($session) => $session->agent === test_agent_name()
                )
            ) > 0
        );
    }

